```

**JavaScript (script.js):**

```javascript
const canvas = document.getElementById('sliderCanvas');
const ctx = canvas.getContext('2d');
const valueDisplay = document.getElementById('valueDisplay');
const centerX = canvas.width / 2;
const centerY = canvas.height / 2;
let radius = 0;
let maxRadius = Math.min(centerX, centerY) - 10; // Leave some border space

canvas.addEventListener('mousedown', startDragging);
canvas.addEventListener('mousemove', drag);
canvas.addEventListener('mouseup', endDragging);
canvas.addEventListener('mouseleave', endDragging);


function startDragging(e) {
  const rect = canvas.getBoundingClientRect();
  const x = e.clientX - rect.left - centerX;
  const y = e.clientY - rect.top - centerY;
  radius = Math.sqrt(x * x + y * y);
  radius = Math.min(radius, maxRadius); // Constrain radius
  draw();
}

function drag(e) {
  const rect = canvas.getBoundingClientRect();
  const x = e.clientX - rect.left - centerX;
  const y = e.clientY - rect.top - centerY;
  radius = Math.sqrt(x * x + y * y);
  radius = Math.min(radius, maxRadius); // Constrain radius
  draw();
}

function endDragging() {
  //Optional: Add any actions to perform when dragging ends
}


function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  // Draw concentric circles
  for (let i = 10; i <= maxRadius; i += 10) {
    ctx.beginPath();
    ctx.strokeStyle = i === radius ? 'red' : 'lightgray'; // Highlight selected circle
    ctx.arc(centerX, centerY, i, 0, 2 * Math.PI);
    ctx.stroke();
  }
  //Draw the main circle
  ctx.beginPath();
  ctx.strokeStyle = 'blue';
  ctx.arc(centerX, centerY, radius, 0, 2 * Math.PI);
  ctx.stroke();

  valueDisplay.textContent = `Radius: ${Math.round(radius)}px`;
}

draw(); //Initial draw
```

Remember to create the three files (`index.html`, `style.css`, `script.js`) in the same directory.  This code uses a canvas element for drawing the circles.  The user clicks and drags on the canvas to adjust the radius.  The selected circle is highlighted in red.  The radius is displayed below the canvas.  Error handling and more sophisticated UI elements could be added for a more robust solution.  This provides a functional base to build upon. Remember to adjust the `maxRadius` and the increment in the `for` loop to fit your design preferences.

