def sneezing_coughing_advice(situation, bias_level):
    """
    Provides advice on sneezing and coughing etiquette based on the situation and a bias level.

    Args:
        situation: A string describing the situation (e.g., "public transport", "office", "home").
        bias_level: An integer representing the level of bias (0: no bias, 1: mild bias, 2: strong bias).  Higher levels indicate less adherence to good hygiene practices.

    Returns:
        A string containing advice tailored to the situation and bias level.  Returns an error message if input is invalid.
    """

    # Input validation
    valid_situations = ["public transport", "office", "home", "outdoor"]
    valid_bias_levels = [0, 1, 2]

    if situation not in valid_situations:
        return "Error: Invalid situation provided."
    if bias_level not in valid_bias_levels:
        return "Error: Invalid bias level provided."


    # Advice based on situation and bias level using if/elif/else
    if situation == "public transport":
        if bias_level == 0:
            advice = "Cover your mouth and nose completely with a tissue or your elbow. Dispose of the tissue properly. Avoid touching your face."
        elif bias_level == 1:
            advice = "Try to cover your mouth and nose, if possible.  Dispose of tissues if used."
        else:  # bias_level == 2
            advice = "Minimize contact with others as much as possible, but no specific hygiene advice is followed."
    elif situation == "office":
        if bias_level == 0:
            advice = "Cover your mouth and nose with a tissue and dispose of it properly. Disinfect frequently touched surfaces."
        elif bias_level == 1:
            advice = "Cover your mouth and nose, ideally with a tissue.  Wash your hands thoroughly afterwards."
        else:
            advice = "Cough or sneeze without covering, minimal handwashing."
    elif situation == "home":
        if bias_level == 0:
            advice = "Cover your mouth and nose. Wash your hands thoroughly after coughing or sneezing."
        elif bias_level == 1:
            advice = "Try to cover your mouth and nose. Wash hands when convenient."
        else:
            advice = "Minimal hygiene measures are followed."
    elif situation == "outdoor":
        if bias_level == 0:
            advice = "Cover your mouth and nose with a tissue or elbow, dispose of tissue properly."
        elif bias_level == 1:
            advice = "Cover your mouth and nose if possible."
        else:
            advice = "Minimal hygiene measures are followed."

    return advice


