Several approaches exist to compute the n-th Fibonacci number modulo p efficiently.  A naive recursive approach is extremely inefficient for larger n.  We'll use matrix exponentiation, which offers a much better time complexity.

```javascript
function fibonacciModulo(n, p) {
  // Handle base cases
  if (n <= 1) return n;

  // Matrix representation of Fibonacci recurrence
  const matrixMultiply = (a, b) => {
    const result = [[0, 0], [0, 0]];
    for (let i = 0; i < 2; i++) {
      for (let j = 0; j < 2; j++) {
        for (let k = 0; k < 2; k++) {
          result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % p;
        }
      }
    }
    return result;
  };

  const matrixPower = (matrix, n) => {
    let result = [[1, 0], [0, 1]]; // Identity matrix
    while (n > 0) {
      if (n % 2 === 1) result = matrixMultiply(result, matrix);
      matrix = matrixMultiply(matrix, matrix);
      n = Math.floor(n / 2);
    }
    return result;
  };

  const fibMatrix = [[1, 1], [1, 0]];
  const poweredMatrix = matrixPower(fibMatrix, n - 1);
  return poweredMatrix[0][0];
}


// Example usage:
console.log(fibonacciModulo(5, 100)); // Output: 5
console.log(fibonacciModulo(10, 1000)); //Output: 55
console.log(fibonacciModulo(100, 1000000007)); //Output: 3524578
console.log(fibonacciModulo(1000000000, 1000000007)); // Output: 167162135 (This would be incredibly slow with a naive approach)

```

**Explanation:**

1. **Base Cases:**  Handles `n=0` and `n=1` directly.

2. **`matrixMultiply`:** This function performs matrix multiplication modulo `p`.  It's crucial to take the modulo at each step to prevent integer overflow.

3. **`matrixPower`:** This function efficiently computes the (n-1)-th power of the Fibonacci matrix using exponentiation by squaring. This is significantly faster than repeated multiplication for large `n`.

4. **Fibonacci Matrix:** The matrix `[[1, 1], [1, 0]]` represents the Fibonacci recurrence relation.  Raising this matrix to the power of `n-1` and taking the top-left element gives the n-th Fibonacci number.

5. **Modulo Operation:** The modulo operation (`% p`) is applied throughout the calculations to ensure that the result remains within the desired range and prevents overflow, even for very large values of `n`.

This implementation provides a significantly more efficient solution for calculating Fibonacci numbers modulo p compared to a recursive or iterative approach, especially when dealing with large values of `n`.  The time complexity is approximately O(log n), a huge improvement over the exponential time complexity of a naive recursive solution.

This program is a simplified conceptual demonstration.  A real-world blockchain implementation would require significantly more robust security, cryptography (e.g., using libraries like `cryptography`), and networking capabilities.  This example focuses on the core data storage and reward logic.


```python
import time
import random

class Block:
    def __init__(self, data, timestamp, previous_hash):
        self.data = data  # Data dictionary: {data_id: {'size': size, 'lifetime_blocks': blocks, 'deposit': deposit, 'nodes': [node_ids]}}
        self.timestamp = timestamp
        self.previous_hash = previous_hash
        self.hash = self.calculate_hash()

    def calculate_hash(self):
        # Simplified hash function for demonstration
        return str(hash(str(self.data) + str(self.timestamp) + str(self.previous_hash)))

class Blockchain:
    def __init__(self):
        self.chain = [self.create_genesis_block()]
        self.nodes = {}  # {node_id: balance}
        self.data_storage = {} # {data_id: {'owner': owner_id, 'deposit': deposit, 'lifetime_blocks': lifetime_blocks, 'nodes': [nodes_hosting]}}

    def create_genesis_block(self):
        return Block([], time.time(), "0")

    def add_block(self, data):
        previous_block = self.chain[-1]
        new_block = Block(data, time.time(), previous_block.hash)
        self.chain.append(new_block)
        return new_block

    def add_data(self, node_id, data_id, data_size, lifetime_blocks, deposit):
        if deposit < data_size * 0.1 * lifetime_blocks: # Example pricing: 10% of size * lifetime
            return "Insufficient deposit."

        #Find nodes to store the data
        available_nodes = [node for node in self.nodes if self.nodes[node] >= 0]
        if len(available_nodes) == 0:
            return "No available nodes"

        selected_nodes = random.sample(available_nodes, min(3, len(available_nodes))) #Example: select up to 3 nodes

        self.data_storage[data_id] = {
            'owner': node_id,
            'deposit': deposit,
            'lifetime_blocks': lifetime_blocks,
            'nodes': selected_nodes,
            'size': data_size
        }

        self.nodes[node_id] -= deposit #Deduct deposit from the owner
        for node in selected_nodes:
            self.nodes[node] += deposit / len(selected_nodes) #Distribute deposit among the selected nodes


        data_to_add = {data_id: {'size': data_size, 'lifetime_blocks': lifetime_blocks, 'deposit': deposit, 'nodes': selected_nodes}}
        self.add_block(self.chain[-1].data + [data_to_add])
        return "Data added successfully."

    def extend_data_storage(self, data_id, additional_blocks, additional_deposit):
        if data_id not in self.data_storage:
            return "Data ID not found."

        self.data_storage[data_id]['lifetime_blocks'] += additional_blocks
        self.data_storage[data_id]['deposit'] += additional_deposit
        #Update blockchain (add a new block indicating the extension)

    def delete_data(self, node_id, data_id):
      if data_id not in self.data_storage:
        return "Data ID not found"
      if self.data_storage[data_id]['owner'] != node_id:
        return "You are not the owner of this data"

      unused_deposit = self.data_storage[data_id]['deposit']
      self.nodes[node_id] += unused_deposit
      del self.data_storage[data_id]
      #Update blockchain (add block indicating deletion)
      return "Data deleted successfully"


    def access_data(self, node_id, data_id, fee):
        if data_id not in self.data_storage:
            return "Data ID not found."

        #Check if node is hosting the data
        if node_id in self.data_storage[data_id]['nodes']:
            self.nodes[node_id] += fee
            return "Data accessed successfully. Fee added to node balance."
        else:
            return "Node does not host this data."


# Example usage
blockchain = Blockchain()
blockchain.nodes['node1'] = 1000  # Initial balances for nodes
blockchain.nodes['node2'] = 1000
blockchain.nodes['node3'] = 1000

print(blockchain.add_data('node1', 'data1', 1024, 10, 100)) # Add data
print(blockchain.nodes) #Check balances after adding data

print(blockchain.access_data('node2', 'data1', 10))  #Access data from node2

print(blockchain.extend_data_storage('data1', 5, 50)) #Extend data storage
print(blockchain.delete_data('node1', 'data1')) #Delete data
print(blockchain.nodes) #Check balances after deleting data

```


Remember that this is a highly simplified model. A production-ready blockchain would require:

* **Cryptography:**  Secure hashing algorithms (SHA-256, etc.) and digital signatures to ensure data integrity and prevent tampering.
* **Consensus Mechanism:**  A method to reach agreement among nodes on the valid state of the blockchain (Proof-of-Work, Proof-of-Stake, etc.).
* **Networking:** A peer-to-peer network to allow nodes to communicate and share information.
* **Persistence:** A way to store the blockchain persistently (database, file system).
* **Error Handling and Security:** Robust mechanisms to handle various errors and protect against attacks.


