This Flask app uses a simple dictionary for authentication.  For production use,  **never** store passwords in plain text.  Use a proper hashing mechanism like bcrypt or Argon2.

```python
from flask import Flask, request, Response

app = Flask(__name__)

# **INSECURE - ONLY FOR DEMO PURPOSES!** Replace with a secure authentication system.
user_passwords = {
    "user": "password",
    "admin": "adminpassword"
}

def check_auth(username, password):
    """This function is called to check if a username /
    password combination is valid.
    """
    if username in user_passwords and user_passwords[username] == password:
        return True
    return False

def authenticate():
    """Sends a 401 response that enables basic auth"""
    return Response(
    "Could not verify your access level for that URL.\n"
    "You have to login with proper credentials", 401,
    {'WWW-Authenticate': 'Basic realm="Login Required"'}
    )

def requires_auth(f):
    """Decorator to protect a view function with HTTP Basic Auth"""
    def decorated(*args, **kwargs):
        auth = request.authorization
        if not auth or not check_auth(auth.username, auth.password):
            return authenticate()
        return f(*args, **kwargs)
    return decorated


@app.route("/")
@requires_auth
def index():
    return "<h1>Welcome! You are authenticated.</h1>"


if __name__ == "__main__":
    app.run(debug=True) #debug=True is for development only, disable in production

```

