This program uses a text-based interface to play Connect 4.  It includes error handling and checks for a win condition.

```python
import numpy as np

ROW_COUNT = 6
COLUMN_COUNT = 7

def create_board():
    """Creates an empty Connect 4 board."""
    return np.zeros((ROW_COUNT, COLUMN_COUNT))

def drop_piece(board, row, col, piece):
    """Drops a piece onto the board."""
    board[row][col] = piece

def is_valid_location(board, col):
    """Checks if a column is a valid location to drop a piece."""
    return board[ROW_COUNT - 1][col] == 0

def get_next_open_row(board, col):
    """Gets the next open row in a column."""
    for r in range(ROW_COUNT):
        if board[r][col] == 0:
            return r

def print_board(board):
    """Prints the board to the console."""
    print(np.flip(board, 0))

def winning_move(board, piece):
    """Checks if the last move resulted in a win."""
    # Check horizontal
    for c in range(COLUMN_COUNT - 3):
        for r in range(ROW_COUNT):
            if board[r][c] == piece and board[r][c + 1] == piece and board[r][c + 2] == piece and board[r][c + 3] == piece:
                return True

    # Check vertical
    for c in range(COLUMN_COUNT):
        for r in range(ROW_COUNT - 3):
            if board[r][c] == piece and board[r + 1][c] == piece and board[r + 2][c] == piece and board[r + 3][c] == piece:
                return True

    # Check positively sloped diagonals
    for c in range(COLUMN_COUNT - 3):
        for r in range(ROW_COUNT - 3):
            if board[r][c] == piece and board[r + 1][c + 1] == piece and board[r + 2][c + 2] == piece and board[r + 3][c + 3] == piece:
                return True

    # Check negatively sloped diagonals
    for c in range(COLUMN_COUNT - 3):
        for r in range(3, ROW_COUNT):
            if board[r][c] == piece and board[r - 1][c + 1] == piece and board[r - 2][c + 2] == piece and board[r - 3][c + 3] == piece:
                return True

    return False

def play_connect_four():
    """Plays a game of Connect 4."""
    board = create_board()
    game_over = False
    turn = 0

    while not game_over:
        # Ask for player input
        if turn == 0:
            col = int(input("Player 1 (1): Choose a column (1-7): ")) - 1
        else:
            col = int(input("Player 2 (2): Choose a column (1-7): ")) - 1

        # Validate input
        if col < 0 or col >= COLUMN_COUNT:
            print("Invalid column number. Please choose a column between 1 and 7.")
            continue

        if not is_valid_location(board, col):
            print("Column is full. Choose another column.")
            continue

        row = get_next_open_row(board, col)
        if turn == 0:
            drop_piece(board, row, col, 1)
        else:
            drop_piece(board, row, col, 2)

        print_board(board)

        if winning_move(board, 1):
            print("Player 1 wins!")
            game_over = True
        elif winning_move(board, 2):
            print("Player 2 wins!")
            game_over = True
        elif np.all(board != 0): #check for a draw
            print("It's a draw!")
            game_over = True

        turn += 1
        turn = turn % 2


if __name__ == "__main__":
    play_connect_four()

```

To run this code, save it as a Python file (e.g., `connect4.py`) and run it from your terminal using `python connect4.py`.  The game will then start in your console. Remember to install NumPy if you haven't already: `pip install numpy`

